SELECT CAST('processDefinition' AS TEXT) AS kind, definition_id AS record_id, workspace_id AS workspace_id, CAST(NULL AS TEXT) AS board_id, name AS business_name, version AS business_version, source_hash AS source_hash, payload AS payload, router_time AS router_time, time_basis AS time_basis, origin_installation AS origin_installation, origin_machine AS origin_machine, import_digest AS import_digest FROM process_definitions WHERE name = ? AND version = ?;
